#!/usr/bin/env bash
# Run every k6 scenario RUNS times against the Compose stack and save raw output.
#
#   scripts/run_benchmarks.sh            # full suite (~35 min)
#   RUNS=1 PROFILES=baseline scripts/run_benchmarks.sh   # quick check
#
# Output: benchmarks/results/<timestamp>/ with raw k6 JSON + stdout per run,
# docker stats samples per run, environment.txt, and SUMMARY.md (generated by
# scripts/summarize_benchmarks.py from those files only).
set -euo pipefail
cd "$(dirname "$0")/.."

RUNS="${RUNS:-3}"
PROFILES="${PROFILES:-baseline load}"
STAMP="$(date -u +%Y%m%dT%H%M%SZ)"
OUT_DIR="benchmarks/results/$STAMP"
mkdir -p "$OUT_DIR"

profile_vus() { case "$1" in baseline) echo 10 ;; load) echo 50 ;; esac; }
profile_duration() {
  if [[ -n "${QUICK:-}" ]]; then echo 10s; return; fi  # pipeline check only, not for results
  case "$1" in baseline) echo 60s ;; load) echo 120s ;; esac
}
FAIL_ARGS=(-e VUS=10 -e DURATION=80s -e FAIL_AT=20 -e RECOVER_AT=50)
RL_ARGS=(-e VUS=5 -e SECONDS=30)
if [[ -n "${QUICK:-}" ]]; then
  FAIL_ARGS=(-e VUS=10 -e DURATION=20s -e FAIL_AT=5 -e RECOVER_AT=12)
  RL_ARGS=(-e VUS=5 -e SECONDS=10)
  OUT_DIR="benchmarks/results/tmp/$STAMP"; mkdir -p "$OUT_DIR"
fi

echo "Starting stack (gateway x2, backends, redis, monitoring)..."
docker compose --profile multi up -d --build >/dev/null
scripts/smoke_test.sh >/dev/null

{
  echo "timestamp_utc: $STAMP"
  echo "git_commit: $(git rev-parse --short HEAD 2>/dev/null || echo unknown)"
  echo "machine: $(sysctl -n machdep.cpu.brand_string 2>/dev/null || uname -m), $(sysctl -n hw.ncpu 2>/dev/null) cores, $(( $(sysctl -n hw.memsize 2>/dev/null || echo 0) / 1073741824 )) GiB RAM"
  echo "os: $(sw_vers -productName 2>/dev/null) $(sw_vers -productVersion 2>/dev/null) ($(uname -sr))"
  echo "docker: $(docker version --format '{{.Server.Version}}'), VM: $(docker info --format '{{.NCPU}} CPUs, {{.MemTotal}} bytes')"
  echo "relay_image_python: $(docker compose exec -T relay python --version)"
  echo "relay_image_packages: $(docker compose exec -T relay pip freeze 2>/dev/null | grep -Ei '^(fastapi|starlette|uvicorn|httpx|redis|uvloop|httptools)==' | tr '\n' ' ')"
  echo "k6: $(docker compose --profile bench run --rm k6 version 2>/dev/null | head -1)"
  echo "topology: k6, relay, backend-a/b, redis all in Docker on one bridge network; single uvicorn worker per service"
  echo "workload: closed-loop GET (no think time); responses ~0.5 KB JSON from the mock backend"
  echo "runs_per_scenario: $RUNS; profiles: $PROFILES"
} > "$OUT_DIR/environment.txt"
cat "$OUT_DIR/environment.txt"

sample_stats() {  # sample container CPU/mem once per second until killed
  local file="$1"
  while true; do
    docker stats --no-stream --format '{{.Name}},{{.CPUPerc}},{{.MemUsage}}' \
      | sed "s/^/$(date +%s),/" >> "$file" 2>/dev/null || true
    sleep 1
  done
}

run_k6() {  # name script extra-env...
  local name="$1" script="$2"; shift 2
  echo ">>> $name"
  sample_stats "$OUT_DIR/$name.stats.csv" &
  local sampler=$!
  docker compose --profile bench run --rm -e "OUT=/results/${OUT_DIR#benchmarks/results/}/$name.json" "$@" \
    k6 run --quiet "/scripts/$script" > "$OUT_DIR/$name.txt" 2>&1 || true
  kill "$sampler" 2>/dev/null; wait "$sampler" 2>/dev/null || true
  grep -E 'rps|latency|failed|ratio|allowed|ceiling|GATEWAY_COUNTERS' "$OUT_DIR/$name.txt" | sed 's/^/    /' || true
  sleep 5  # let connections drain between runs
}

for run in $(seq 1 "$RUNS"); do
  for profile in $PROFILES; do
    vus=$(profile_vus "$profile"); dur=$(profile_duration "$profile")
    # Interleave scenarios within each run so drift affects all of them equally.
    run_k6 "direct-$profile-run$run"           direct.js  -e VUS="$vus" -e DURATION="$dur"
    run_k6 "gateway-uncached-$profile-run$run" gateway.js -e VUS="$vus" -e DURATION="$dur" -e MODE=uncached
    run_k6 "gateway-cached-$profile-run$run"   gateway.js -e VUS="$vus" -e DURATION="$dur" -e MODE=cached
  done
  run_k6 "failure-run$run"   failure.js   "${FAIL_ARGS[@]}"
  run_k6 "ratelimit-run$run" ratelimit.js "${RL_ARGS[@]}"
done

.venv/bin/python scripts/summarize_benchmarks.py "$OUT_DIR" 2>/dev/null || python3 scripts/summarize_benchmarks.py "$OUT_DIR"
echo "Results: $OUT_DIR/SUMMARY.md"
